import os
import torch


class Config:
    """
    Global configuration for the Ventilator Pressure Prediction task.
    Implements the settings for the Multi-Scale Dense-Hybrid Network (MSDH-Net).
    """

    # -------------------------------------------------------------------------
    # File Paths & Directories
    # -------------------------------------------------------------------------
    # Input Metadata (Generated by metadata script)
    METADATA_DIR = "./metadata"
    TRAIN_CSV = os.path.join(METADATA_DIR, "train.csv")
    VAL_CSV = os.path.join(METADATA_DIR, "validation.csv")
    TEST_CSV = os.path.join(METADATA_DIR, "test.csv")

    # Original Input (for sample submission structure)
    SAMPLE_SUBMISSION_PATH = "./input/sample_submission.csv"

    # Working Directory (for caching intermediate data and models)
    # Using 'idea_15' as the designated workspace for this iteration
    WORKING_DIR = "./working/idea_15"
    CACHE_DIR = WORKING_DIR

    # Model Checkpoint Path
    MODEL_SAVE_PATH = os.path.join(WORKING_DIR, "best_model.pth")

    # Submission Output
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # Create necessary writable directories
    os.makedirs(WORKING_DIR, exist_ok=True)
    os.makedirs(SUBMISSION_DIR, exist_ok=True)

    # -------------------------------------------------------------------------
    # Data Pipeline Configuration
    # -------------------------------------------------------------------------
    SEED = 42
    NUM_WORKERS = 4

    # Sequence Properties
    SEQ_LEN = 80  # Standard breath length

    # Column Names
    ID_COL = "id"
    BREATH_ID_COL = "breath_id"
    TARGET_COL = "pressure"
    TIME_COL = "time_step"

    # Feature Engineering Configuration
    # The model expects a specific order of features in the input tensor.
    # 1. Dynamic State: u_in, u_out, area (integral), u_in_diff (derivative)
    # 2. Temporal Context: time_step
    # 3. Static Physics: R, C, R_u_in (interaction), area_C (interaction)
    # 4. Lookahead: u_in (t+1..t+4), u_in_diff (t+1)
    FEATURE_COLS = [
        "u_in",  # Control input
        "u_out",  # Expiratory valve state
        # "time_step",  # Removed to enforce dynamic learning (Cite solution_lesson_node_00047)
        "R",  # Resistance
        "C",  # Compliance
        "area",  # Physically accurate volume (Integral u_in * dt)
        "u_in_diff",  # Acceleration (Derivative of u_in)
        "R_u_in",  # Interaction: R * u_in
        "area_C",  # Interaction: area / C
        "u_in_next1",  # Lookahead t+1
        "u_in_next2",  # Lookahead t+2
        "u_in_next3",  # Lookahead t+3
        "u_in_next4",  # Lookahead t+4
        "u_in_diff_next1",  # Lookahead derivative t+1
    ]

    INPUT_DIM = len(FEATURE_COLS)  # Should be 14

    # -------------------------------------------------------------------------
    # Model Hyperparameters (MSDH-Net)
    # -------------------------------------------------------------------------
    # Branch 1: Multi-Scale Dense CNN (Resistive Stream)
    # Parallel convolutions with different kernel sizes to capture multi-scale dynamics
    CNN_KERNELS = [3, 7, 11]
    CNN_FILTERS = 64
    CNN_ACTIVATION = "gelu"

    # Branch 2: High-Capacity Bidirectional LSTM (Elastic Stream)
    # Serves as the numerical integrator
    LSTM_HIDDEN_SIZE = 512
    LSTM_LAYERS = 3
    LSTM_BIDIRECTIONAL = True
    LSTM_DROPOUT = 0.0  # Dropout applied between LSTM layers (if layers > 1)

    # Fusion Head
    # Concatenates CNN and LSTM outputs
    FC_HIDDEN_UNITS = 256
    FC_DROPOUT = 0.1

    # -------------------------------------------------------------------------
    # Training Configuration
    # -------------------------------------------------------------------------
    # Optimization
    BATCH_SIZE = 128  # Small batch size for gradient noise regularization
    EPOCHS = 80  # Extended training for hybrid convergence
    LEARNING_RATE = 1e-3
    WEIGHT_DECAY = 1e-2  # For AdamW

    # Learning Rate Scheduler (ReduceLROnPlateau)
    SCHEDULER_PATIENCE = 5
    SCHEDULER_FACTOR = 0.5
    MIN_LR = 1e-6

    # Loss Function
    # We use Masked MAE (calculated only where u_out == 0)
    LOSS_METRIC = "L1"

    # Hardware
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    # -------------------------------------------------------------------------
    # Debugging & Development
    # -------------------------------------------------------------------------
    # Set DEBUG to True or set MAX_TRAIN_SAMPLES to a small integer to run a quick check
    DEBUG = False
    MAX_TRAIN_SAMPLES = None  # e.g., 1000 for quick debugging
    MAX_VAL_SAMPLES = None
